<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {KnowledgeEntry} from './knowledge-model';
const props=defineProps<{entries:KnowledgeEntry[];selected:string;redact:(v:unknown)=>string}>(),emit=defineEmits<{select:[path:string]}>();
const opened=ref(new Set<string>()),filter=ref(''),scroll=ref(0),box=ref<HTMLElement>();
watch(()=>props.selected,p=>{const parts=p.split('/');for(let i=1;i<parts.length;i++)opened.value.add(parts.slice(0,i).join('/'));});
const rows=computed(()=>{const result:{path:string;title:string;folder:boolean;depth:number}[]=[],seen=new Set<string>(),q=filter.value.toLowerCase();for(const n of [...props.entries].sort((a,b)=>a.path.localeCompare(b.path))){if(q&&!`${n.path} ${n.title} ${n.uid??''}`.toLowerCase().includes(q))continue;const parts=n.path.split('/');let visible=true;for(let i=1;i<parts.length;i++){const path=parts.slice(0,i).join('/');if(visible&&!seen.has(path)){result.push({path,title:parts[i-1]!,folder:true,depth:i-1});seen.add(path);}if(!q&&!opened.value.has(path))visible=false;}if(visible||q)result.push({path:n.path,title:n.title,folder:false,depth:parts.length-1});}return result;});
const start=computed(()=>Math.max(0,Math.floor(scroll.value/34)-5)),slice=computed(()=>rows.value.slice(start.value,start.value+28));
watch(()=>props.selected,()=>{const i=rows.value.findIndex(r=>r.path===props.selected);if(i>=0&&box.value){box.value.scrollTop=i*34;scroll.value=i*34;}},{flush:'post'});
function choose(r:{path:string;folder:boolean}){if(r.folder){if(opened.value.has(r.path))opened.value.delete(r.path);else opened.value.add(r.path);}else emit('select',r.path);}
</script>
<template><nav aria-label="知识目录树" class="kb-tree"><input v-model="filter" aria-label="筛选目录树" placeholder="查找目录或文档" @input="scroll=0;box?.scrollTo?.(0,0)"/><div ref="box" class="kb-tree-scroll" @scroll="scroll=($event.target as HTMLElement).scrollTop"><div :style="{height:rows.length*34+'px',position:'relative'}"><button v-for="(row,i) in slice" :key="row.path" :style="{position:'absolute',top:(start+i)*34+'px',paddingLeft:(row.depth*14+8)+'px'}" :aria-current="!row.folder&&selected===row.path?'page':undefined" :aria-expanded="row.folder?opened.has(row.path):undefined" :title="redact(row.path)" @click="choose(row)">{{row.folder?(opened.has(row.path)?'▾ ':'▸ '):'· '}}{{redact(row.title)}}</button></div></div><small>{{entries.length}} 篇文档</small></nav></template>
<style scoped>.kb-tree{min-width:0;padding:12px;border:1px solid var(--ocp-border);border-radius:10px}.kb-tree input{width:100%;padding:8px;border:1px solid var(--ocp-border);background:var(--ocp-background);color:var(--ocp-foreground);border-radius:6px}.kb-tree-scroll{height:560px;overflow:auto;margin-top:8px}.kb-tree button{height:34px;width:100%;text-align:left;border:0;border-radius:4px;background:transparent;color:inherit;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.kb-tree button:hover,.kb-tree button[aria-current=page]{background:var(--ocp-muted-background);color:var(--ocp-primary)}small{color:var(--ocp-muted)}</style>
